package org.jsoup;

import java.io.IOException;

public class UncheckedIOException extends RuntimeException {

    public UncheckedIOException(final IOException ioException) {
        super(ioException);
    }

    public IOException ioException() {
        final IOException cause = (IOException) this.getCause();
        return cause;
    }
}
